def hero_title():
 from html import escape
 lines=['Seu sorriso,','nosso melhor','cuidado.']
 count=0; chunks=[]
 for line in lines:
  letters=[]
  for char in line:
   letters.append(f'<span class="hero-letter" style="--letter:{count}">{escape(char)}</span>');count+=1
  chunks.append('<span class="hero-line" aria-hidden="true">'+''.join(letters)+'</span>')
 return '<h1 aria-label="Seu sorriso, nosso melhor cuidado.">'+''.join(chunks)+'</h1>'
